def reconstructMatrix(upper, lower, colsum):
    n = len(colsum)
    A0 = [0]*n
    A1 = [0]*n
    for i in range(n):
        if colsum[i] == 2:
            A0[i] = 1
            A1[i] = 1
            upper -= 1
            lower -= 1
    for i in range(n):
        if colsum[i] == 1:
            if upper > 0:
                A0[i] = 1
                upper -= 1
            else:
                A1[i] = 1
                lower -= 1
    if upper == 0 and lower == 0:
