def maximize_advantage(A, B):
    sorted_A = sorted(A)
    sorted_B = sorted([(b, i) for i, b in enumerate(B)], reverse=True)
    result = [0] * len(A)
    left, right = 0, len(A) -1
    for b, i in sorted_B:
        if sorted_A[right] > b:
            result[i] = sorted_A[right]
            right -=1
        else:
            result[i] = sorted_A[left]
            left +=1
    return result

