import re
from collections import Counter

def most_frequent_word(paragraph, banned):
    # Normalize the paragraph to lowercase
    paragraph = paragraph.lower()
    # Replace punctuation with spaces
    paragraph = re.sub(r'[!?\',;.]', ' ', paragraph)
    # Split into words
    words = paragraph.split()
    # Create a set of banned words for faster lookup
    banned_set = set(banned)
    # Count the frequency of each non-banned word
    counts = Counter(word for word in words if word not in banned_set)
    # Return the most common word
    return counts.most_common(1)[0][0]

def run_tests():
    test_cases = [
        {
            "paragraph": "Bob hit a ball, the hit BALL flew far after it was hit.",
            "banned": ["hit"],
            "expected": "ball"
        },
        {
            "paragraph": "a.",
            "banned": [],
            "expected": "a"
        },
        {
            "paragraph": "Jack and Jill went to the market to buy bread and cheese. Cheese is Jack's and Jill's favorite food.",
            "banned": ["and", "he", "the", "to", "is", "jack's", "jill's"],
            "expected": "cheese"
        },
        {
            "paragraph": "It was the best of times, it was the worst of times.",
            "banned": ["it", "was", "the", "of"],
            "expected": "times"
        },
        {
            "paragraph": "Hello, hello! HELLO?",
            "banned": [],
            "expected": "hello"
        },
        {
            "paragraph": "a a a b b c",
            "banned": ["a"],
            "expected": "b"
        }
    ]

    correct = 0
    total = len(test_cases)

    for test in test_cases:
        output = most_frequent_word(test["paragraph"], test["banned"])
        result = output == test["expected"]
        print(result)
        if result:
            correct += 1
    print(f"{correct}/{total}")

if __name__ == "__main__":
    run_tests()

import heapq

def skyline_test():
    def get_skyline(buildings):
        # Create events: (x, height, is_start)
        events = []
        for left, right, height in buildings:
            events.append((left, -height, True))  # start event
            events.append((right, height, False))  # end event
        # Sort events. If x is the same, start events come before end events
        events.sort(key=lambda x: (x[0], x[1]))

        result = []
        heap = [0]  # Max-heap (as min-heap with negative heights)
        active = {}
        prev = 0

        for x, h, is_start in events:
            if is_start:
                heapq.heappush(heap, h)
                active[h] = active.get(h, 0) + 1
            else:
                active[-h] -= 1
                if active[-h] == 0:
                    del active[-h]
            # Clean the heap
            while heap and (-heap[0] not in active):
                heapq.heappop(heap)
            current = -heap[0] if heap else 0
            if current != prev:
                result.append([x, current])
                prev = current
        return result

    test_cases = [
        {
            "buildings": [[2,9,10],[3,7,15],[5,12,12],[15,20,10],[19,24,8]],
            "expected": [[2,10],[3,15],[7,12],[12,0],[15,10],[20,8],[24,0]]
        },
        {
            "buildings": [[0,2,3],[2,5,3]],
            "expected": [[0,3],[5,0]]
        },
        {
