def remove_outer_parentheses(S: str) -> str:
    result = []
    depth = 0
    for char in S:
        if char == '(':
            if depth > 0:
                result.append(char)
            depth += 1
        else:
            depth -= 1
            if depth > 0:
                result.append(char)
    return ''.join(result)

def run_tests():
    tests = [
        ("(()())(())", "()()()"),
        ("(()())(())(()(()))", "()()()()(())"),
