from functools import lru_cache
from collections import Counter

def run_tests():
    def alice_wins(nums):
        initial_xor = 0
        for num in nums:
            initial_xor ^= num

        counter = Counter(nums)
        unique_nums = tuple(sorted(counter.items()))

        @lru_cache(None)
        def can_win(state, current_xor):
            if current_xor == 0:
                return True  # Current player wins
            state_counter = Counter(dict(state))
            for num in state_counter:
                next_xor = current_xor ^ num
                if state_counter[num] == 1:
                    next_state = tuple(sorted((k, v) for k, v in state_counter.items() if k != num))
                else:
                    next_state = tuple(sorted((k, v-1) if k == num else (k, v) for k, v in state_counter.items()))
                if next_xor == 0:
                    continue  # This move makes current_xor 0, which is a losing move
                opponent_can_win = can_win(next_state, next_xor)
                if not opponent_can_win:
                    return True  # Current player can force a win
            return False  # No winning moves

        return can_win(unique_nums, initial_xor)

    test_cases = [
        # (nums, expected_output)
        ([1, 1, 2], False),
        ([0], True),
        ([1, 2, 3], True),
        ([4, 4, 4, 4], True),
        ([1, 2, 1, 2], True),
        ([1, 1, 1], False),
        ([2, 2, 3, 3, 4], True),
        ([5, 5, 5, 5, 5], False),
        ([7, 7, 7, 7, 7, 7], True),
        ([8], True)
    ]

    correct = 0
    total = len(test_cases)
    for idx, (nums, expected) in enumerate(test_cases, 1):
        result = alice_wins(nums)
        test_passed = result == expected
        print(test_passed)
        if test_passed:
            correct += 1
    print(f"{correct}/{total}")

run_tests()

from fractions import Fraction
from collections import deque

def least_operations(x, target):
    from fractions import Fraction
    from collections import deque

    # BFS initialization
    queue = deque()
    queue.append((Fraction(x), 0))
    visited = set()
    visited.add(Fraction(x))

    while queue:
        current, ops = queue.popleft()
        if current == target:
            return ops
        # Apply operations
        for op in ['+', '-', '*', '/']:
            if op == '+':
                next_val = current + x
            elif op == '-':
                next_val = current - x
            elif op == '*':
                next_val = current * x
            elif op == '/':
                if x != 0:
                    next_val = current / x
                else:
                    continue
            if next_val not in visited:
                visited.add(next_val)
                queue.append((next_val, ops + 1))
    return -1  # If target is not reachable

def run_tests():
    tests = [
        ((3, 19), 5),
        ((5, 501), 8),
        ((100, 100000000), 3)
    ]
    correct = 0
    total = len(tests)
    for i, ((x, target), expected) in enumerate(tests):
        result = least_operations(x, Fraction(target))
        if result == expected:
            print(True)
            correct += 1
        else:
            print(False)
    print(f"{correct}/{total}")

run_tests()

