def minimum_length_encoding(words):
    unique_words = set(words)
    for word in words:
        for k in range(1, len(word)):
            suffix = word[k:]
            if suffix in unique_words:
                unique_words.discard(suffix)
    return sum(len(word) + 1 for word in unique_words)

def run_tests():
    test_cases = [
        (["time", "me", "bell"], 10),
        (["t"], 2),
        (["time", "ime", "me", "e"], 6),
        (["a", "b", "c"], 6),
        (["apple", "ple", "pple"], 6),
        (["abc", "bc", "c"], 4),
        (["cat","bat","rat"], 12),
        (["leetcode","code","leetcode"], 10),
        (["aabbcc","aabbcc","aabbcc"], 7),
        (["xyz","yz","z"], 4)
    ]
    correct = 0
    total = len(test_cases)
    for words, expected in test_cases:
        result = minimum_length_encoding(words)
        if result == expected:
            print(True)
            correct +=1
        else:
            print(False)
    print(f"{correct}/{total}")

run_tests()

from collections import deque

def openLock(deadends, target):
    dead = set(deadends)
    if "0000" in dead:
        return -1
    visited = set("0000")
    queue = deque([("0000", 0)])

    while queue:
        state, steps = queue.popleft()
        if state == target:
            return steps
        for i in range(4):
            digit = int(state[i])
            for move in (-1, 1):
                new_digit = (digit + move) % 10
                new_state = state[:i] + str(new_digit) + state[i+1:]
                if new_state not in dead and new_state not in visited:
                    visited.add(new_state)
