from collections import Counter

def can_reorder_doubled(arr):
    count = Counter(arr)
    if len(arr) % 2 != 0:
        return False
    # Sort the keys based on absolute value
    for x in sorted(count.keys(), key=abs):
        if count[x] > count.get(2 * x, 0):
            return False
        count[2 * x] -= count[x]
    return True

