def findMaxValueOfEquation(points, k):
    import heapq
    max_val = float('-inf')
    heap = []  # max heap, store (-yi + xi, xi)
    for x, y in points:
        while heap and x - heap[0][1] > k:
            heapq.heappop(heap)
        if heap:
            max_val = max(max_val, y + x + heap[0][0])
        heapq.heappush(heap, (-(y - x), x))
    return max_val

