# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree(lst):
    if not lst:
        return None
    root = TreeNode(lst[0])
    queue = deque([root])
    i = 1
    n = len(lst)
    while queue and i < n:
        node = queue.popleft()
        if i < n and lst[i] is not None:
            node.left = TreeNode(lst[i])
            queue.append(node.left)
        i += 1
        if i < n and lst[i] is not None:
            node.right = TreeNode(lst[i])
            queue.append(node.right)
        i += 1
    return root

def find_target_node(root, target_val):
    if not root:
        return None
    queue = deque([root])
    while queue:
        node = queue.popleft()
        if node.val == target_val:
            return node
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)
    return None

def distanceK(root, target, K):
    parent = {}
    def dfs(node, par=None):
        if node:
            parent[node] = par
            dfs(node.left, node)
