def addOperators(num: str, target: int):
    res = []
    n = len(num)

    def helper(index, path, evaluated, multed):
        if index == n:
            if evaluated == target:
                res.append(path)
            return
        for i in range(index, n):
            # Avoid numbers with leading zero
            if i != index and num[index] == '0':
                break
            curr_str = num[index:i+1]
            curr = int(curr_str)
            if index == 0:
                helper(i+1, curr_str, curr, curr)
            else:
                helper(i+1, path + '+' + curr_str, evaluated + curr, curr)
                helper(i+1, path + '-' + curr_str, evaluated - curr, -curr)
                helper(i+1, path + '*' + curr_str, evaluated - multed + multed * curr, multed * curr)

    helper(0, "", 0, 0)
    return res

test_cases = [
    ("123", 6, ["1*2*3","1+2+3"]),
    ("232", 8, ["2*3+2","2+3*2"]),
    ("105", 5, ["1*0+5","10-5"]),
    ("00", 0, ["0+0","0-0","0*0"]),
    ("3456237490", 9191, [])
]

correct = 0
total = len(test_cases)

for num, target, expected in test_cases:
    output = addOperators(num, target)
    if sorted(output) == sorted(expected):
        print('True')
        correct +=1
    else:
        print('False')

print(f"{correct}/{total}")

# Precompute smallest prime factors up to 100,000
MAX = 100001
spf = [0] * MAX
for i in range(2, MAX):
    if spf[i] == 0:
        spf[i] = i
        if i * i < MAX:
            for j in range(i * i, MAX, i):
                if spf[j] == 0:
                    spf[j] = i
# For 0 and 1
spf[0] = spf[1] = 1

def largest_component_size(A):
    from collections import defaultdict

    # Union-Find implementation
    parent = list(range(len(A)))
    size = [1] * len(A)

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return
        if size[u_root] < size[v_root]:
            parent[u_root] = v_root
            size[v_root] += size[u_root]
        else:
            parent[v_root] = u_root
            size[u_root] += size[v_root]

    factor_map = {}
    for idx, num in enumerate(A):
        x = num
        factors = set()
        while x > 1:
            factor = spf[x]
            factors.add(factor)
            while x % factor == 0:
                x //= factor
        for factor in factors:
            if factor in factor_map:
                union(idx, factor_map[factor])
            else:
                factor_map[factor] = idx

    # Count the size of each connected component
    count = defaultdict(int)
    for i in range(len(A)):
        root = find(i)
        count[root] +=1
    return max(count.values()) if count else 0

def run_tests():
    tests = [
        ([4,6,15,35], 4),
        ([20,50,9,63], 2),
        ([2,3,6,7,4,12,21,39], 8)
    ]
