def numDistinct(s: str, t: str) -> int:
    m, n = len(s), len(t)
    if n == 0:
        return 1
    if m < n:
        return 0
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, m + 1):
        # Iterate backwards to ensure dp[j-1] refers to the previous state
        for j in range(n, 0, -1):
            if s[i - 1] == t[j - 1]:
                dp[j] += dp[j - 1]
    return dp[n]

