        grid_copy = deepcopy(test["grid"])
        result = count_distinct_islands(grid_copy)
        pass_test = result == test["expected"]
        print(pass_test)
        if pass_test:
            correct += 1
    print(f"{correct}/{len(tests)}")

run_tests()
